const formatMs = (value: number | null) => value === null ? "—" : `${Math.round(value)} ms`;
const formatRate = (value: number | null) => value === null ? "—" : `${(value * 100).toFixed(1)}%`;
const formatMoney = (value: number | null, currency = "USD") => value === null ? "—" : new Intl.NumberFormat("en-US", { style: "currency", currency, minimumFractionDigits: 4, maximumFractionDigits: 6 }).format(value);
const objectValue = (value: unknown): Record<string, unknown> => typeof value === "object" && value !== null ? value as Record<string, unknown> : {};
const numericValue = (value: unknown): number | null => typeof value === "number" ? value : null;
const patternNames = ["A", "A2", "B", "C", "Hosted"] as const;
const hostedModes = ["tool", "context-semantic", "context-agentic"] as const;
