function useExperiments() {
  const [items, setItems] = useState<ExperimentSummary[]>([]);
  const [error, setError] = useState("");
  useEffect(() => void benchmarkApi.experiments().then((data) => setItems(data.items)).catch((reason: Error) => setError(reason.message)), []);
  return { items, error };
}

function usePatterns() {
  const [items, setItems] = useState<PatternSummaryResponse["item"][]>([]);
  const [error, setError] = useState("");
  useEffect(() => void Promise.all(patternNames.map((pattern) => benchmarkApi.pattern(pattern))).then((values) => setItems(values.map((value) => value.item))).catch((reason: Error) => setError(reason.message)), []);
  return { items, error };
}

function useEvidenceLinks() {
  const [links, setLinks] = useState<Record<string, { status: string; url?: string; releaseStatus: string }>>({});
  const [error, setError] = useState("");
  useEffect(() => {
    void Promise.all(evidenceDestinations.map(async ({ type }) => {
      const result = await benchmarkApi.nativeLink(type, "current");
      return [type, { status: result.status, url: result.authoritative_url ?? undefined, releaseStatus: result.release_status }] as const;
    })).then((values) => setLinks(Object.fromEntries(values))).catch((reason: Error) => setError(reason.message));
  }, []);
  return { links, error };
}

function useDecision(goal: "quality" | "balanced" | "speed", experiments: ExperimentSummary[] = [], scopeOverride?: string) {
  const [decision, setDecision] = useState<DecisionResponse | null>(null);
  const [error, setError] = useState("");
  useEffect(() => {
    let active = true;
    setDecision(null);
    setError("");
    const applyDecision = (value: DecisionResponse) => { if (active) setDecision(value); };
    const applyError = (reason: Error) => { if (active) setError(reason.message); };
    if (scopeOverride) {
      void benchmarkApi.decision(goal, scopeOverride).then(applyDecision).catch(applyError);
      return () => { active = false; };
    }
    void benchmarkApi.decision(goal).then(async (initial) => {
      if (initial.selected_scope || !experiments.length) return initial;
      const byId = new Map(experiments.map((item) => [item.experiment_id, item]));
      const preferred = [...initial.available_scopes].filter((scope) => scope.experiment_ids.length >= 2).sort((left, right) => {
        const score = (scope: typeof left) => scope.experiment_ids.reduce((total, id) => { const item = byId.get(id); const hasQuality = item?.quality !== null && item?.quality !== undefined; const hasCost = item?.estimated_variable_cost !== null && item?.estimated_variable_cost !== undefined; return total + (hasQuality ? 100000 : 0) + (hasCost ? 60000 : 0) + (item?.count ?? 0); }, 0);
        return score(right) - score(left);
      })[0];
      return preferred ? benchmarkApi.decision(goal, preferred.scope_id) : initial;
    }).then(applyDecision).catch(applyError);
    return () => { active = false; };
  }, [goal, experiments, scopeOverride]);
  return { decision, error };
}

function State({ message }: { message: string }) { return <div className="state"><AlertTriangle size={18} />{message}</div>; }
const AGENTIC_PHASE_TYPES = new Set(["modelQueryPlanning", "searchIndex", "agenticReasoning"]);
function laneName(boundary: string): string {
  if (boundary.startsWith("copilot_studio")) return "Copilot Studio front door";
  if (boundary.startsWith("agent_framework_local")) return "local";
  if (boundary.startsWith("foundry_hosted_agent")) return "deployed";
  if (boundary.startsWith("foundry_responses") || boundary.startsWith("direct_") || boundary.startsWith("deterministic")) return "component";
  return boundary || "scope";
}
function scopeLabel(scope: { experiment_ids: string[] }, items: ExperimentSummary[]): string {
  const byId = new Map(items.map((item) => [item.experiment_id, item]));
  const patterns = [...new Set(scope.experiment_ids.map((id) => byId.get(id)?.pattern).filter(Boolean))];
  const lanes = [...new Set(scope.experiment_ids.map((id) => laneName(String((byId.get(id)?.provenance as Record<string, unknown> | undefined)?.measurement_boundary ?? ""))))];
  const lane = lanes.length === 1 ? lanes[0] : "mixed lanes";
  return `${patterns.join(" / ") || "Scope"} · ${lane} · ${scope.experiment_ids.length} runs`;
}
function Metric({ label, value, detail }: { label: string; value: string; detail?: string }) { return <div className="metric"><span>{label}</span><strong>{value}</strong>{detail && <small>{detail}</small>}</div>; }

function ExperimentTable({ items }: { items: ExperimentSummary[] }) {
  if (!items.length) return <State message="No experiment artifacts are configured." />;
  return <div className="table-wrap"><table><thead><tr><th>Experiment</th><th>Architecture</th><th>p95 latency</th><th>Success</th><th>Quality</th><th>Evidence</th><th aria-label="Open" /></tr></thead><tbody>{items.map((item) => <tr key={item.experiment_id}><td><Link href={`/experiments/${item.experiment_id}`}>{item.experiment_id}</Link><small>{item.dataset_name} · v{item.dataset_version}</small></td><td><span className={`pattern pattern-${item.pattern.toLowerCase()}`}>{item.pattern}</span><small>{modeLabel(item.retrieval_mode)} · <span className="lane-tag">{laneName(String((item.provenance as Record<string, unknown> | undefined)?.measurement_boundary ?? ""))}</span></small></td><td className="numeric">{formatMs(item.latency_p95_ms)}</td><td className="numeric">{formatRate(item.success_rate)}</td><td className="numeric">{formatRate(item.quality)}</td><td><span className={item.sample_warning ? "evidence-tag caution" : "evidence-tag"}>{item.sample_warning ? <AlertTriangle size={12} /> : <CheckCircle2 size={12} />}{item.count} samples</span>{item.provenance.fixture_mode === true && <small>Fixture only</small>}</td><td><Link className="row-action" aria-label={`Open ${item.experiment_id}`} href={`/experiments/${item.experiment_id}`}><ChevronRight size={17} /></Link></td></tr>)}</tbody></table></div>;
}

function PatternCards({ items }: { items: PatternSummaryResponse["item"][] }) {
  return <div className="pattern-grid architecture-grid">{items.map((item) => <article key={item.pattern} className={`architecture-card evidence-${item.evidence_status}`}><div className="architecture-heading"><span className="pattern-label">{item.pattern}</span><span className={`evidence-state ${item.evidence_status}`}>{evidenceLabel(item.evidence_status)}</span></div><h3>{item.latest ? modeLabel(item.latest.retrieval_mode) : "Adapter ready"}</h3><p>{item.automation_boundary}</p><dl><dt>Implementation</dt><dd>{item.implementation_status}</dd><dt>Artifacts</dt><dd>{item.experiment_count}</dd><dt>Telemetry</dt><dd>{item.telemetry_boundary}</dd></dl>{item.latest && <Link href={`/experiments/${item.latest.experiment_id}`}>Inspect {item.evidence_status === "fixture_only" ? "fixture" : "evidence"} <ArrowRight size={14} /></Link>}</article>)}</div>;
}

function EvidenceSourceGuide({ links }: { links: Record<string, { status: string; url?: string; releaseStatus: string }> }) {
  return <div className="evidence-guide-grid">{evidenceDestinations.map((source) => { const link = links[source.type]; const connectionLabel = link?.status === "available" ? "Link available" : link?.status ? `Link ${link.status.replace(/_/g, " ")}` : "Checking link"; const surfaceStatus = "previewNote" in source ? source.previewNote : link?.releaseStatus; return <article className="evidence-source" key={source.type}><div className="source-heading"><div><span className="source-index">{String(evidenceDestinations.indexOf(source) + 1).padStart(2, "0")}</span><div className="source-title"><h3>{source.name}</h3>{surfaceStatus && <small>{surfaceStatus}</small>}</div></div><span className={`connection-state ${link?.status ?? "not_configured"}`}>{connectionLabel}</span></div><div className="source-trigger"><h4>Use this when</h4><p>{source.useWhen}</p></div><div className="source-scope"><div><h4>Shown in this workbench</h4><p>{source.workbench}</p></div><div><h4>Inspect in the native system</h4><ul>{source.native.map((metric) => <li key={metric}>{metric}</li>)}</ul></div></div><h4>How to investigate</h4><ol>{source.steps.map((step) => <li key={step}>{step}</li>)}</ol><div className="source-action">{link?.url ? <a href={link.url} target="_blank" rel="noreferrer">Open {source.name} <ExternalLink size={14} /></a> : <span>Configure <code>{source.configuration}</code> on the server</span>}</div></article>; })}</div>;
}

export function Overview() {
  const { items, error } = useExperiments();
  const { items: patterns, error: patternError } = usePatterns();
  const [goal, setGoal] = useState<"quality" | "balanced" | "speed">("quality");
  const { decision, error: decisionError } = useDecision(goal, items);
  if (error || decisionError || patternError) return <State message={error || decisionError || patternError} />;
  const recommended = items.find((item) => item.experiment_id === decision?.recommended_experiment_id); const leading = items.find((item) => item.experiment_id === decision?.leading_experiment_id);
  // Keep the hosted retrieval-mode comparison on one boundary: the token-priced local Agent Framework lane (the pinned publication). Exclude deployed foundry_hosted_agent runs and prefer the publication lineage so it matches decision-system-20260811 (tool 100% / semantic 71.4% / agentic 100%).
  const modeEvidence = hostedModes.map((mode) => items.filter((item) => item.pattern === "Hosted" && item.retrieval_mode === mode && item.quality !== null && item.estimated_variable_cost !== null && String((item.provenance as Record<string, unknown> | undefined)?.measurement_boundary ?? "").startsWith("agent_framework_local")).sort((left, right) => Number(right.experiment_id.includes("publication")) - Number(left.experiment_id.includes("publication")) || right.count - left.count || right.created_at.localeCompare(left.created_at))[0] ?? null);
  const gaps = patterns.filter((item) => item.evidence_status !== "measured");
  const measuredPatterns = patterns.filter((item) => item.evidence_status === "measured").length;
  const runByPattern = Object.fromEntries(patternNames.map((pattern) => [pattern, items.filter((item) => item.pattern === pattern).sort((a, b) => b.created_at.localeCompare(a.created_at))[0]?.experiment_id]).filter(([, id]) => id)) as Record<string, string>;

  return <section className="page overview-page"><header className="page-head overview-head"><div><p className="eyebrow">Benchmark decision system</p><h1>Grounded agent — architecture benchmark</h1><p className="lede">One shared workload across five retrieval patterns, scored on quality, latency, reliability, and cost — with release gates and deep links to the owning Azure service.</p></div><div className="evidence-summary"><span className="live-dot" /><div><strong>{items.length} benchmark runs</strong><small>{measuredPatterns} of {patternNames.length} patterns currently have measured evidence</small></div></div></header>
    <ArchitectureMap runByPattern={runByPattern} />
    <BenchmarkCharts items={items} />
    <section className="command-stats" aria-label="Evidence summary"><article><Layers3 size={18} /><span>Architecture paths</span><strong>{patternNames.length}</strong><small>A, A2, B, C, and Hosted</small></article><article><Trophy size={18} /><span>Hosted modes graded</span><strong>{modeEvidence.filter(Boolean).length}/3</strong><small>Deterministic quality measured; model judges are supplemental</small></article><article><ShieldCheck size={18} /><span>Native systems connected</span><strong>{evidenceDestinations.length}</strong><small>Operational evidence stays with its Azure owner</small></article><article className="gap-stat"><AlertTriangle size={18} /><span>Patterns needing benchmark evidence</span><strong>{gaps.length}</strong><small>Fixture-only or controlled run required</small></article></section>

    <section className="decision-ribbon"><div><span className="decision-kicker"><Sparkles size={15} /> Decision status</span><strong>{recommended ? `${modeLabel(recommended.retrieval_mode)} currently qualifies` : leading ? `Leading — ${leading.pattern} · ${modeLabel(leading.retrieval_mode)}` : "No comparable evidence to recommend yet"}</strong><p>{recommended ? decision?.selection_method : leading ? decision?.leading_reason : decision?.blockers[decision.blockers.length - 1] ?? "Run comparable evidence to qualify a path."}</p></div><div className="segment light" role="group" aria-label="Recommendation goal">{(["quality", "balanced", "speed"] as const).map((option) => <button key={option} className={goal === option ? "active" : ""} aria-pressed={goal === option} onClick={() => setGoal(option)}>{option === "quality" ? <Trophy size={15} /> : option === "balanced" ? <Gauge size={15} /> : <Timer size={15} />}{option}</button>)}</div><Link href="/pareto">Inspect gates <ArrowRight size={15} /></Link></section>

    <section className="nav-guide" aria-label="How to navigate"><div className="section-title"><div><p className="eyebrow">Start here</p><h3>What this is — and how to move around it</h3><p>A read-only decision workbench that compares grounded-agent retrieval patterns (Copilot Studio A / A2 / C, Foundry B, and the Hosted agent) on one shared workload, then links out to Azure for the operational detail. Follow the tabs left to right: measure → compare → qualify → operate.</p></div></div><div className="nav-guide-grid">{[["/experiments", Activity, "Experiments", "Every measured run — latency, quality, security, cost. Open one to drill into its evidence."], ["/compare", GitCompareArrows, "Compare", "Put two compatible runs side by side. Refuses to rank runs whose scope differs."], ["/pareto", ScrollText, "Pareto / SLO", "Which options clear the release gates (quality, p95, success, security, cost) and why."], ["/coverage", ScanSearch, "Evidence coverage", "What is normalized here vs owned by Azure — plus deep links to App Insights, Grafana, Foundry, Search, and Cost Management."], ["/glossary", BookText, "Glossary", "Plain-language definitions — Pareto, p95, deterministic quality, measurement boundary, and more."]].map(([to, Icon, title, desc]) => { const I = Icon as typeof Activity; return <Link key={String(to)} href={String(to)} className="nav-guide-card"><span className="nav-guide-icon"><I size={18} /></span><div><strong>{String(title)}</strong><p>{String(desc)}</p></div><ChevronRight size={16} className="nav-guide-arrow" /></Link>; })}</div></section>

    <section className="benchmark-positioning" aria-labelledby="benchmark-positioning-title"><header><p className="eyebrow">Why this workbench exists</p><h2 id="benchmark-positioning-title">Azure tools explain each system. This benchmark helps you choose across them.</h2><p>No single native view compares every Copilot Studio architecture using the same workload and decision rules. This workbench joins that evidence without recreating Azure’s monitoring, evaluation, capacity, load, or billing products.</p></header><div className="positioning-columns"><div><h3>Decision gaps this fills</h3><ul className="gap-list"><li><strong>Cross-pattern comparison</strong><span>A, A2, B, C, and Hosted use one normalized contract.</span></li><li><strong>Apples-to-apples evidence</strong><span>Incompatible datasets, indexes, models, or run boundaries are not ranked together.</span></li><li><strong>Release qualification</strong><span>Quality, security, latency, reliability, cost, sample size, and SLO gates produce an explainable recommendation.</span></li><li><strong>Missing-evidence visibility</strong><span>Fixture-only, run-required, unavailable, and measured states remain explicit.</span></li></ul></div><div><h3>What remains Azure-native</h3><ul className="native-list"><li><strong>Copilot Studio</strong><span>Employee entry point, orchestration, channels, and pattern integration.</span></li><li><strong>Application Insights + Grafana</strong><span>Production traces, latency trends, failures, dashboards, and alerts.</span></li><li><strong>Foundry + Azure AI Search</strong><span>Evaluation drill-down, agent traces, retrieval behavior, and Search capacity.</span></li><li><strong>Cost Management</strong><span>Actual Azure billing reconciled against the benchmark's variable-cost estimates.</span></li></ul><Link className="positioning-link" href="/coverage">Open native investigation guide <ArrowRight size={14} /></Link></div></div></section>

    <section className="integration-model" aria-labelledby="integration-model-title"><div className="section-title"><div><p className="eyebrow">Integration model</p><h3 id="integration-model-title">When to use the benchmark and when to stay native</h3><p>The lead system changes as the architecture moves from design to production.</p></div></div><ol><li><span className="stage-number">01</span><div><small>Design · Benchmark leads</small><strong>Run the same cases through candidate patterns.</strong><p>Keep each pattern as a separate Copilot Studio route or test agent; capture normalized results and native trace or evaluation IDs.</p></div></li><li><span className="stage-number">02</span><div><small>Release · Benchmark leads</small><strong>Compare only compatible runs and apply gates.</strong><p>Use Compare and Pareto / SLO before changing the production route, model, index, prompt, or retrieval mode.</p></div></li><li><span className="stage-number">03</span><div><small>Production · Azure services lead</small><strong>Operate the selected pattern in Azure services.</strong><p>Copilot Studio serves users. Application Insights, Grafana, Foundry, Search, and Cost Management own live operational detail.</p></div></li><li><span className="stage-number">04</span><div><small>Improve · Both work together</small><strong>Turn production findings into repeatable tests.</strong><p>Add representative failures or slow cases to the controlled dataset, rerun candidates, and validate the change before release.</p></div></li></ol></section>

    <div className="section-title"><div><p className="eyebrow">Hosted retrieval</p><h3>Quality is measured across all three modes</h3><p>Same 35-case release scope; deterministic gates remain authoritative and model judges are supplemental.</p></div><Link href="/compare">Compare runs <ArrowRight size={15} /></Link></div>
    <div className="mode-comparison">{hostedModes.map((mode, index) => { const item = modeEvidence[index]; return <article key={mode}><div className="mode-heading"><span>{modeLabel(mode)}</span><span className={item ? "evidence-state measured" : "evidence-state run_required"}>{item ? `${item.count} cases` : "Run required"}</span></div>{item ? <><strong>{formatRate(item.quality)}</strong><small>Deterministic quality</small><dl><dt>Security</dt><dd>{formatRate(item.security_pass_rate)}</dd><dt>p95 latency</dt><dd>{formatMs(item.latency_p95_ms)}</dd><dt>Est. model cost</dt><dd>{formatMoney(item.estimated_variable_cost)}</dd></dl><Link href={`/experiments/${item.experiment_id}`}>Open evidence <ArrowRight size={14} /></Link></> : <p>No graded artifact is indexed for this mode.</p>}</article>; })}</div>

    <div className="section-title"><div><p className="eyebrow">Architecture paths</p><h3>Implementation and evidence are separate states</h3><p>Every pattern now has measured evidence; implementation status and evidence status remain distinct signals.</p></div></div>
    <PatternCards items={patterns} />

    <div className="section-title ledger-title"><div><p className="eyebrow">Evidence ledger</p><h3>Recent runs</h3></div><Link href="/experiments">Explore all experiments <ArrowRight size={15} /></Link></div><ExperimentTable items={items.slice(0, 6)} />
    <section className="reuse-footer"><div><h3>Open, adaptable benchmark harness</h3><p><strong>Fork this workbench for your own agents.</strong> Every chart and gate is driven by normalized JSON contracts (<code>manifest</code>, <code>aggregate</code>, <code>evaluation</code>) — swap in your patterns, datasets, and pricing profile, and the comparison, release gates, and visuals adapt automatically.</p></div><Link href="/coverage">See the contracts <ArrowRight size={15} /></Link></section></section>;
}

export function Experiments() {
  const { items, error } = useExperiments();
  const [latestOnly, setLatestOnly] = useState(true);
  if (error) return <State message={error} />;
  const laneOf = (item: ExperimentSummary) => laneName(String((item.provenance as Record<string, unknown> | undefined)?.measurement_boundary ?? ""));
  const shown = latestOnly
    ? Object.values(items.reduce<Record<string, ExperimentSummary>>((acc, item) => {
        const key = `${item.pattern}|${item.retrieval_mode}|${item.dataset_name}|${item.dataset_version}|${laneOf(item)}`;
        if (!acc[key] || item.created_at > acc[key].created_at) acc[key] = item;
        return acc;
      }, {})).sort((a, b) => (a.created_at < b.created_at ? 1 : -1))
    : items;
  return <section className="page"><header className="page-head"><div><p className="eyebrow">Evidence ledger</p><h2>Experiments</h2><p className="lede">Every controlled benchmark run. Each row is one committed artifact — with its dataset, measurement boundary, latency, reliability, quality, security, and cost. This is the raw evidence the Compare and Pareto views build on.</p></div></header><div className="chart-card ledger-chart"><div className="chart-card-head"><p className="eyebrow">Latency by run</p><h3>p95 across {shown.length} runs</h3><p className="chart-hint">Each bar is one run, coloured by pattern; the dashed line is the 30 s p95 SLO. Sorted slowest first — distinct from the per-pattern summary on Overview.</p></div><RunLatencyChart items={shown} /></div><div className="section-title"><div><p className="eyebrow">All runs</p><h3>{shown.length} of {items.length} experiments</h3><p>Each row is a distinct configuration — pattern × retrieval mode × dataset version × measurement boundary. “Latest per configuration” hides superseded re-runs; switch to full history to audit every run. Click any run to open its report.</p></div><button type="button" className={latestOnly ? "toggle-pill active" : "toggle-pill"} aria-pressed={latestOnly} onClick={() => setLatestOnly((value) => !value)}>{latestOnly ? "Latest per configuration" : "Full run history"}</button></div><ExperimentTable items={shown} /></section>;
}

export function ExperimentDetail() {
  const { id = "" } = useParams(); const { items, error } = useExperiments(); const item = items.find((candidate) => candidate.experiment_id === id); const [report, setReport] = useState<ExperimentReport | null>(null); const [detailError, setDetailError] = useState("");
  useEffect(() => { if (id) void benchmarkApi.experiment(id).then(setReport).catch((reason: Error) => setDetailError(reason.message)); }, [id]);
  if (error || detailError) return <State message={error || detailError} />; if (!item || !report) return <State message="Experiment not found or still loading." />;
  const { aggregate } = report; const provenance = aggregate.provenance; const nativeMethods = objectValue(provenance.evaluation_native_methods); const nativeReleaseBlockers = Array.isArray(provenance.evaluation_release_blockers) ? provenance.evaluation_release_blockers.map(String) : []; const judgeScores = objectValue(provenance.judge_scores); const calibration = objectValue(provenance.judge_calibration); const runCost = aggregate.variable_cost.run_total; const categoryRows = Object.entries(aggregate.by_category); const qualityRows = Object.entries(aggregate.quality_by_category ?? {}); const successInterval = aggregate.rate_confidence_intervals?.success_rate; const isCopilotStudio = String(provenance.measurement_boundary ?? "") === "copilot_studio_direct_line"; const copilotCredits = objectValue(provenance.copilot_credits); const agenticPhaseRows = Object.entries(aggregate.by_activity_type).filter(([type]) => AGENTIC_PHASE_TYPES.has(type)); const pricedCount = aggregate.variable_cost.priced_invocation_count; const invocationCount = aggregate.variable_cost.invocation_count;
  return <section className="page"><header className="page-head"><div><p className="eyebrow">Experiment detail</p><h2>{item.experiment_id}</h2></div><span className="pattern">Pattern {item.pattern}</span></header>
    <div className="metrics"><Metric label="p50" value={formatMs(item.latency_p50_ms)} detail="Median response" /><Metric label="p95" value={formatMs(item.latency_p95_ms)} detail="95% completed at or below" /><Metric label="p99" value={formatMs(item.latency_p99_ms)} detail="99% completed at or below" /><Metric label="Success" value={formatRate(item.success_rate)} /><Metric label="Quality" value={formatRate(item.quality)} /><Metric label="Security" value={formatRate(item.security_pass_rate)} /><Metric label="Run model cost" value={formatMoney(runCost.amount, runCost.currency)} detail={`${aggregate.variable_cost.priced_invocation_count}/${aggregate.variable_cost.invocation_count} priced`} /></div>
    <section className="latency-guide" aria-labelledby="latency-guide-title"><div><p className="eyebrow">Latency guide</p><h3 id="latency-guide-title">How to read latency percentiles</h3><p>These are client-observed end-to-end response times for this controlled run. Lower is better, and only compatible runs should be compared.</p></div><dl><div><dt>p50 · typical</dt><dd>Half of requests completed in <strong>{formatMs(item.latency_p50_ms)}</strong> or less. This is the median, not the average.</dd></div><div><dt>p95 · slow experience</dt><dd>95% completed in <strong>{formatMs(item.latency_p95_ms)}</strong> or less; the slowest 5% took longer.</dd></div><div><dt>p99 · extreme tail</dt><dd>99% completed in <strong>{formatMs(item.latency_p99_ms)}</strong> or less. With {item.count} samples, one slow case can move this value substantially.</dd></div></dl></section>
    <div className="section-title"><div><p className="eyebrow">Latency shape</p><h3>Response-time percentiles</h3><p>Bars are scaled to the largest percentile. A wide gap from p50 to p95/p99 means a heavy tail.</p></div></div><div className="chart-card"><SingleRunLatencyChart p50={item.latency_p50_ms} p95={item.latency_p95_ms} p99={item.latency_p99_ms} /></div>
    <div className="detail-grid"><article><h3>Run configuration</h3><dl><dt>Dataset</dt><dd>{item.dataset_name} · v{item.dataset_version}</dd><dt>Corpus</dt><dd><code>{item.corpus_fingerprint ?? "Not recorded"}</code></dd><dt>Index</dt><dd><code>{item.index_fingerprint ?? "Not recorded"}</code></dd><dt>Model deployment</dt><dd>{item.model_deployment ?? "Not applicable"}</dd><dt>Answer model</dt><dd><code>{report.manifest.answer_model ?? "Not recorded"}</code></dd><dt>Retrieval mode</dt><dd>{modeLabel(report.manifest.retrieval_mode)}</dd></dl></article><article><h3>Evidence boundary</h3><p>Controlled-run metrics are separate from production telemetry, load evidence, and billed Azure cost.</p><dl><dt>Outcomes</dt><dd>{aggregate.success_count ?? "—"} success · {aggregate.partial_count ?? "—"} partial · {aggregate.error_count ?? "—"} error · {aggregate.timeout_count ?? "—"} timeout</dd><dt>Success 95% interval</dt><dd>{successInterval ? `${formatRate(successInterval.lower)}–${formatRate(successInterval.upper)} · Wilson` : "Unavailable"}</dd><dt>Throttles</dt><dd>{aggregate.throttle_count ?? "—"} · {formatRate(aggregate.throttle_rate)}</dd><dt>Cold/warm split</dt><dd>{aggregate.cold_client_wall_time || aggregate.warm_client_wall_time ? <span className="hint" title="Warm-up and measured invocations were tagged separately for this run.">Captured</span> : <span className="hint" title="This run did not tag warm-up vs. measured invocations, so cold-start and warm latency are not separated. Add warm-up tagging to the run to capture it.">Unavailable</span>}</dd><dt>Stage timing</dt><dd>{Object.keys(aggregate.by_stage).length ? <span className="hint" title="Per-stage spans (e.g. retrieve vs. generate) were emitted for this run.">Captured</span> : <span className="hint" title="This measurement boundary does not emit per-stage spans (e.g. retrieve vs. generate), so stage-level timing cannot be broken out. It is structurally unavailable, not a data gap in this run.">Unavailable</span>}</dd><dt>Provider activity</dt><dd>{agenticPhaseRows.length ? <span className="hint" title="The provider emitted structured agentic activity: query planning, parallel search, and reasoning phases (see below).">Captured</span> : Object.keys(aggregate.by_activity_type).length ? <span className="hint" title="Direct Line returned message activities only. This pattern uses single-shot retrieval, not agentic query planning, so there are no retrieval phases to break out.">Message only</span> : <span className="hint" title="The provider did not expose structured activity for this measurement boundary.">Unavailable</span>}</dd></dl>{item.sample_warning && <State message={item.sample_warning} />}</article></div>
    <div className="section-title"><div><p className="eyebrow">Latency distribution</p><h3>Client-observed request time</h3></div></div>{aggregate.client_wall_time ? <div className="metrics"><Metric label="Minimum" value={formatMs(aggregate.client_wall_time.minimum_ms)} /><Metric label="Mean" value={formatMs(aggregate.client_wall_time.mean_ms)} /><Metric label="Std deviation" value={formatMs(aggregate.client_wall_time.standard_deviation_ms)} /><Metric label="Maximum" value={formatMs(aggregate.client_wall_time.maximum_ms)} /></div> : <State message="Client latency is unavailable." />}
    <div className="section-title"><div><p className="eyebrow">Workload slices</p><h3>Latency by query category</h3></div></div><div className="table-wrap"><table><thead><tr><th>Category</th><th>Samples</th><th>Mean</th><th>p95</th></tr></thead><tbody>{categoryRows.map(([name, summary]) => <tr key={name}><td><code>{name}</code></td><td className="numeric">{summary.count}</td><td className="numeric">{formatMs(summary.mean_ms)}</td><td className="numeric">{formatMs(summary.p95_ms)}</td></tr>)}</tbody></table></div>
    {agenticPhaseRows.length > 0 && <><div className="section-title"><div><p className="eyebrow">Agentic retrieval phases</p><h3>Query planning and retrieval activity</h3><p>White-box view of agentic retrieval: the Knowledge Base decomposes the question into sub-queries, searches each, and merges results. Captured directly by the benchmark (no workflow orchestrator needed); sub-query text stays in the run's sanitized JSONL. Only patterns that use agentic retrieval show this section.</p></div></div><div className="agentic-flow-wrap"><AgenticFlow /></div><div className="table-wrap"><table><thead><tr><th>Phase</th><th>Records</th><th>Elapsed p50</th><th>Reasoning tokens</th></tr></thead><tbody>{agenticPhaseRows.map(([type, phase]) => <tr key={type}><td><code>{type}</code></td><td className="numeric">{phase.record_count}</td><td className="numeric">{phase.elapsed_ms ? formatMs(phase.elapsed_ms.p50_ms) : "—"}</td><td className="numeric">{phase.reasoning_tokens || "—"}</td></tr>)}</tbody></table></div></>}
    <div className="section-title"><div><p className="eyebrow">Deterministic slices</p><h3>Quality by query category</h3></div></div>{qualityRows.length ? <div className="table-wrap"><table><thead><tr><th>Category</th><th>Passed</th><th>Pass rate</th><th>95% interval</th></tr></thead><tbody>{qualityRows.map(([name, summary]) => <tr key={name}><td><code>{name}</code></td><td className="numeric">{summary.passed}/{summary.count}</td><td className="numeric">{formatRate(summary.pass_rate)}</td><td className="numeric">{formatRate(summary.confidence_interval.lower)}–{formatRate(summary.confidence_interval.upper)}</td></tr>)}</tbody></table></div> : <State message="Category-level deterministic quality is not attached to this run." />}
    <div className="section-title"><div><p className="eyebrow">Evaluation replay</p><h3>Native methods, deterministic gates, and judge calibration</h3></div></div><div className="detail-grid"><article>{isCopilotStudio ? <><h3>Copilot Studio evaluation</h3><dl>{Object.entries(nativeMethods).map(([name, raw]) => { const method = objectValue(raw); return <span className="definition-row" key={name}><dt>{name}</dt><dd>{formatRate(numericValue(method.pass_rate))} · {numericValue(method.passed) ?? 0}/{numericValue(method.count) ?? 0}</dd></span>; })}{!Object.keys(nativeMethods).length && <span className="muted-note">Native run not yet imported</span>}<dt>Run ID</dt><dd><code>{String(provenance.evaluation_run_id ?? "Not attached")}</code></dd><dt>Test set ID</dt><dd><code>{String(provenance.evaluation_test_set_id ?? "Not attached")}</code></dd><dt>Native release ready</dt><dd>{provenance.evaluation_release_ready === false ? "No" : provenance.evaluation_release_ready === true ? "Yes" : "Not attached"}</dd></dl>{nativeReleaseBlockers.length > 0 && <><h3>Native release blockers</h3><ul>{nativeReleaseBlockers.map((blocker) => <li key={blocker}>{blocker}</li>)}</ul></>}</> : <><h3>Evaluation lane</h3><p className="panel-note">Foundry-native run. Copilot Studio native evaluation does not apply to this pattern — quality and security are graded by a separate deployed-agent replay.</p><dl><dt>Lane</dt><dd><code>{String(provenance.measurement_relationship ?? "deterministic replay")}</code></dd><dt>Evaluation artifact</dt><dd><code>{String(provenance.evaluation_artifact ?? "—")}</code></dd></dl></>}</article><article><h3>Deterministic gates</h3><dl><dt>Quality</dt><dd>{formatRate(item.quality)}</dd><dt>Security</dt><dd>{formatRate(item.security_pass_rate)}</dd><dt>Measurement</dt><dd>{String(provenance.quality_measurement ?? "Not attached")}</dd></dl><h3>Supplemental judges</h3><dl>{Object.entries(judgeScores).map(([name, raw]) => { const score = objectValue(raw); return <span className="definition-row" key={name}><dt>{name.replace(/_/g, " ")}</dt><dd>{numericValue(score.mean)?.toFixed(2) ?? "n/a"}/5 · {formatRate(numericValue(score.pass_rate))}</dd></span>; })}{!Object.keys(judgeScores).length && <span>Not attached</span>}</dl><h3>Agreement</h3><dl>{Object.entries(calibration).map(([name, raw]) => { const score = objectValue(raw); return <span className="definition-row" key={name}><dt>{name.replace(/_/g, " ")}</dt><dd>{formatRate(numericValue(score.agreement_rate))}</dd></span>; })}</dl></article></div>
    <div className="section-title"><div><p className="eyebrow">Cost boundary</p><h3>{isCopilotStudio ? "Cost — Copilot Studio credits" : "Estimated variable model cost"}</h3></div></div>{isCopilotStudio ? <div className="detail-grid"><article><div className="credits-head"><h3>Estimated Credits</h3>{copilotCredits.estimated_total_credits != null && <span className="estimate-tag">estimate — reconcile in admin center</span>}</div>{copilotCredits.estimated_total_credits != null ? <dl><dt>Estimated total</dt><dd><strong>{numericValue(copilotCredits.estimated_total_credits)}</strong> Credits · {numericValue(copilotCredits.interactions)} interactions</dd><dt>Per interaction</dt><dd>{numericValue(copilotCredits.credits_per_interaction)} Credits</dd><dt>Rate card</dt><dd><code>{String(copilotCredits.rate_profile ?? "—")}</code></dd>{copilotCredits.byo_foundry_tokens === true && <><dt>Foundry model tokens</dt><dd>Billed separately on the per-token USD lane</dd></>}</dl> : <p className="muted-note">Credit estimate is unavailable for this pattern.</p>}{copilotCredits.has_uncertain_events === true && <p className="muted-note">Agent-action counts are estimated from configuration; confirm against the admin-center consumption grid.</p>}</article><article><h3>Where to read billed Credits</h3><p className="panel-note">Copilot Studio bills Copilot Credits rated per agent activity (Classic answer 1, Generative answer 2, Agent action 5) — a Microsoft-managed unit that cannot be converted to per-token USD.</p><dl><dt>Billed (authoritative)</dt><dd>Power Platform admin center → Licensing → Copilot Studio → Environments (Copilot credit consumption grid)</dd><dt>Reconcile</dt><dd><code>copilot_credits_cli reconcile</code></dd></dl></article></div> : <div className="detail-grid"><article><dl><dt>Mean per invocation</dt><dd>{formatMoney(aggregate.variable_cost.mean_per_invocation.amount, aggregate.variable_cost.mean_per_invocation.currency)}</dd><dt>Run total</dt><dd>{formatMoney(runCost.amount, runCost.currency)}</dd><dt>Pricing profile</dt><dd><code>{runCost.pricing_profile ?? "Not configured"}</code></dd><dt>Measurement</dt><dd>{runCost.measurement_type}</dd></dl>{pricedCount === 0 ? <p className="muted-note">Per-token usage was not exposed for this run; get tokens from Foundry Monitoring or Application Insights gen_ai spans to price it.</p> : pricedCount < invocationCount ? <p className="muted-note">{pricedCount} of {invocationCount} invocations had service-reported tokens; the rest are unpriced.</p> : <p className="panel-note">Estimate prices service-reported input (context) and output tokens for all {invocationCount} invocations. Larger input reflects the retrieved grounding context; Azure AI Search retrieval compute is excluded (see below).</p>}</article><article><h3>Excluded from estimate</h3>{runCost.excluded_costs.length ? <ul>{runCost.excluded_costs.map((value) => <li key={value}>{value}</li>)}</ul> : <p>Not declared.</p>}<p>Azure Cost Management remains authoritative for billed cost.</p></article></div>}
  </section>;
}

export function Coverage() {
  const { links, error: linkError } = useEvidenceLinks();
  if (linkError) return <State message={linkError} />;
  const connected = Object.values(links).filter((link) => link.status === "available").length;
  return <section className="page"><header className="page-head"><div><p className="eyebrow">Decision-system map</p><h2>Evidence coverage</h2><p className="lede">See which metrics are summarized here and continue into the Azure service that owns the operational detail.</p></div></header><div className="metrics"><Metric label="Evidence boundaries" value="2" /><Metric label="Native destinations" value={String(evidenceDestinations.length)} /><Metric label="Connected destinations" value={`${connected}/${evidenceDestinations.length}`} /><Metric label="Architecture paths" value={String(patternNames.length)} /></div>
    <section className="evidence-boundary" aria-label="Evidence ownership boundary"><div><span className="evidence-state measured">Built into this UI</span><h3>Normalized decision evidence</h3><p>Controlled quality, security, latency, reliability, estimated variable cost, provenance, compatibility, pattern coverage, Pareto, and SLO qualification.</p></div><div><span className="evidence-state run_required">Guided native investigation</span><h3>Authoritative operational detail</h3><p>Trace waterfalls, operational dashboards, evaluation rows, Search capacity, load execution, and billed cost stay in Azure services and open through server-managed links.</p></div></section>
    <div className="section-title" id="evidence-sources"><div><p className="eyebrow">Metric investigation</p><h3>Where to inspect every evidence source</h3><p>Each guide states what is already normalized here, what remains native, and the step-by-step investigation workflow.</p></div></div><EvidenceSourceGuide links={links} />
  </section>;
}

export function Compare() {
  const { items, error } = useExperiments(); const [, navigate] = useLocation(); const search = useSearch(); const params = new URLSearchParams(search);
  const gradedCoverage = new Map<string, Set<string>>();
  items.forEach((item) => { if (item.quality !== null) { (gradedCoverage.get(item.dataset_name) ?? gradedCoverage.set(item.dataset_name, new Set()).get(item.dataset_name)!).add(item.pattern); } });
  const canonicalDataset = [...gradedCoverage.entries()].sort((a, b) => b[1].size - a[1].size)[0]?.[0];
  const latestPerPattern = patternNames.map((pattern) => {
    const runs = items.filter((item) => item.pattern === pattern).sort((a, b) => b.created_at.localeCompare(a.created_at));
    return runs.find((item) => item.dataset_name === canonicalDataset) ?? runs[0];
  }).filter((item): item is ExperimentSummary => Boolean(item));
  const baseline = params.get("baseline") ?? latestPerPattern[0]?.experiment_id ?? "";
  const bItem = items.find((item) => item.experiment_id === baseline);
  const candidateOptions = latestPerPattern.filter((item) => item.experiment_id !== baseline);
  const scopePeer = bItem ? candidateOptions.find((item) => item.comparison_scope === bItem.comparison_scope) : undefined;
  const candidate = params.get("candidate") ?? scopePeer?.experiment_id ?? candidateOptions[0]?.experiment_id ?? "";
  const cItem = items.find((item) => item.experiment_id === candidate);
  const [comparison, setComparison] = useState<ComparisonResponse | null>(null);
  const setParams = (nextBaseline: string, nextCandidate: string) => navigate(`/compare?${new URLSearchParams({ baseline: nextBaseline, candidate: nextCandidate })}`);
  const pickBaseline = (nextBaseline: string) => { const nb = items.find((item) => item.experiment_id === nextBaseline); const peer = nb ? latestPerPattern.find((item) => item.experiment_id !== nextBaseline && item.comparison_scope === nb.comparison_scope) : undefined; const fallback = latestPerPattern.find((item) => item.experiment_id !== nextBaseline); setParams(nextBaseline, peer?.experiment_id ?? fallback?.experiment_id ?? candidate); };
  useEffect(() => { if (baseline && candidate) void benchmarkApi.compare(baseline, candidate).then(setComparison); }, [baseline, candidate]);
  const laneOf = (item?: ExperimentSummary) => laneName(String((item?.provenance as Record<string, unknown> | undefined)?.measurement_boundary ?? ""));
  const deltaEntries = comparison ? Object.entries(comparison.deltas) : [];
  const comparableCount = deltaEntries.filter(([, delta]) => delta.comparable).length;
  if (error) return <State message={error} />;
  if (latestPerPattern.length < 2) return <State message="At least two patterns need a committed run before you can compare." />;
  return <section className="page">
    <header className="page-head"><div><p className="eyebrow">Controlled comparison</p><h2>Compare runs</h2><p className="lede">Put two runs side by side — the pickers list the <strong>most recent run of each pattern</strong> (A, A2, B, C, Hosted). Each metric is judged <strong>on its own terms</strong>: you can fairly compare quality &amp; security across solutions that share a dataset, even when latency &amp; cost aren’t comparable across measurement boundaries. Green tags mark fair comparisons; amber tags name the dimension that blocks one.</p></div></header>
    <div className="pattern-legend" aria-label="Pattern reminder">{patternNames.map((patternName) => <span key={patternName} className="pattern-legend-item"><span className={`pattern pattern-${patternName.toLowerCase()}`}>{patternName}</span>{PATTERN_BLURB[patternName]}</span>)}</div>
    <div className="selectors"><label>Baseline<select value={baseline} onChange={(event) => pickBaseline(event.target.value)}>{latestPerPattern.map((item) => <option key={item.experiment_id} value={item.experiment_id}>{item.pattern} · {item.experiment_id}</option>)}</select>{bItem && <small>Pattern {bItem.pattern} · {bItem.dataset_name} · <strong>{laneOf(bItem)}</strong> lane</small>}</label><label>Candidate<select value={candidate} onChange={(event) => setParams(baseline, event.target.value)}>{candidateOptions.map((item) => <option key={item.experiment_id} value={item.experiment_id}>{item.pattern} · {item.experiment_id}</option>)}</select>{cItem && <small>Pattern {cItem.pattern} · {cItem.dataset_name} · <strong>{laneOf(cItem)}</strong> lane</small>}</label></div>
    {comparison && <>
      <div className={`scope ${comparableCount === deltaEntries.length ? "good" : comparableCount === 0 ? "bad" : "partial"}`}>{comparableCount === deltaEntries.length ? <ShieldCheck size={18} /> : <AlertTriangle size={18} />}<span><strong>{comparableCount} of {deltaEntries.length} metrics</strong> are directly comparable for this pair. Quality &amp; security compare within a shared dataset; latency &amp; reliability within a shared measurement boundary; cost within a shared pricing lane.{comparison.incompatibility_reasons.length > 0 ? ` Full scope differs: ${comparison.incompatibility_reasons.join("; ")}.` : ""}</span></div>
      {bItem && cItem && <p className="muted-note">Answer model — baseline ({bItem.pattern}): <code>{bItem.answer_model ?? bItem.model_deployment ?? "—"}</code> · candidate ({cItem.pattern}): <code>{cItem.answer_model ?? cItem.model_deployment ?? "—"}</code>. Compare quality within a shared model/harness first.</p>}
      <div className="section-title"><div><p className="eyebrow">Deltas · candidate − baseline</p><h3>What changed</h3><p>Each metric is judged independently. A green tag means the difference is a fair comparison; an amber tag names the dimension the two runs differ on, so that metric is shown as —.</p></div></div>
      <div className="metrics">{deltaEntries.map(([name, delta]) => <div key={name} className="metric"><span>{name.replace(/_/g, " ")} <em className={delta.comparable ? "cmp-tag ok" : "cmp-tag no"}>{delta.comparable ? "comparable" : "not comparable"}</em></span><strong>{delta.comparable && delta.absolute !== null ? `${delta.absolute > 0 ? "+" : ""}${delta.absolute.toFixed(3)}` : "—"}</strong><small>{delta.caveat ?? DELTA_HELP[name]}</small></div>)}</div>
      {bItem && cItem && <div className="chart-card" style={{ marginTop: 18 }}><CompareChart baseline={{ id: bItem.experiment_id, p95s: bItem.latency_p95_ms === null ? null : Number((bItem.latency_p95_ms / 1000).toFixed(1)), quality: bItem.quality === null ? null : Number((bItem.quality * 100).toFixed(1)) }} candidate={{ id: cItem.experiment_id, p95s: cItem.latency_p95_ms === null ? null : Number((cItem.latency_p95_ms / 1000).toFixed(1)), quality: cItem.quality === null ? null : Number((cItem.quality * 100).toFixed(1)) }} /></div>}
    </>}
  </section>;
}

export function Pareto() { const { items, error } = useExperiments(); const [scopeSel, setScopeSel] = useState<string | undefined>(undefined); const { decision, error: decisionError } = useDecision("balanced", items, scopeSel); if (error || decisionError) return <State message={error || decisionError} />; const scopeOptions = (decision?.available_scopes ?? []).filter((scope) => scope.experiment_ids.length >= 2); const evidenceIds = new Set(decision?.evidence.map((item) => item.experiment_id) ?? []); const points = items.filter((item) => evidenceIds.has(item.experiment_id) && item.latency_p95_ms !== null && item.quality !== null); const SLO_P95 = 30000, SLO_QUALITY = 0.85; const frontier = decision?.frontier_experiment_ids ?? []; const scatterPoints: ParetoPoint[] = points.map((item) => ({ experimentId: item.experiment_id, pattern: item.pattern, p95s: Number(((item.latency_p95_ms ?? 0) / 1000).toFixed(1)), quality: Number(((item.quality ?? 0) * 100).toFixed(1)), count: item.count, onFrontier: frontier.includes(item.experiment_id) })); return <section className="page"><header className="page-head"><div><p className="eyebrow">Quality versus latency</p><h2>Pareto and SLO</h2><p className="lede">Each point is a comparable run. Further <strong>up</strong> is higher quality; further <strong>left</strong> is faster (lower p95). The shaded corner is the SLO pass region — quality ≥ {formatRate(SLO_QUALITY)} and p95 ≤ {formatMs(SLO_P95)}.</p></div></header>{scopeOptions.length > 1 && <div className="scope-selector"><label>Comparison scope<select value={decision?.selected_scope ?? ""} onChange={(event) => setScopeSel(event.target.value || undefined)}>{scopeOptions.map((scope) => <option key={scope.scope_id} value={scope.scope_id}>{scopeLabel(scope, items)}</option>)}</select></label><p>Only runs sharing a dataset, index, model, retrieval mode, and boundary are ranked together. Switch scope to compare the other patterns.</p></div>}{decision?.blockers.map((blocker) => <State key={blocker} message={blocker} />)}{points.length === 0 ? <State message="No comparable run has both quality and p95 yet. Grade a run in a shared scope to populate this chart." /> : <div className="plot-frame"><ParetoScatter points={scatterPoints} /><div className="plot-legend"><span className="lg frontier">Pareto frontier</span><span className="lg excluded">Dominated</span><span className="lg slo">SLO pass region</span><span className="lg-note">{points.length} comparable run{points.length === 1 ? "" : "s"} in scope{decision?.selected_scope ? ` · ${points.length < 3 ? "add more graded runs in this scope for a fuller frontier" : "frontier reflects non-dominated trade-offs"}` : ""}</span></div></div>}<div className="table-wrap" tabIndex={0} role="region" aria-label="SLO qualification table (scrollable)"><table><thead><tr><th>Experiment</th><th>SLO</th><th>Pareto</th><th>Release-ready</th></tr></thead><tbody>{decision?.evidence.map((item) => <tr key={item.experiment_id}><td>{item.experiment_id}</td><td>{item.qualified ? <span className="evidence-tag"><ShieldCheck size={13} /> Pass</span> : <span className="evidence-tag caution">{item.qualification_failures?.join("; ") || "Fail"}</span>}</td><td>{item.on_pareto_frontier ? "Frontier" : "Excluded"}</td><td>{item.publication_ready ? "Ready" : item.publication_blockers?.join("; ") || "Blocked"}</td></tr>)}</tbody></table></div></section>; }

